TASK AND SPECIFICATIONS
{
  "schema_version": 1,
  "id": "SELF006",
  "kind": "self_built",
  "title": "Tank filling with hysteresis and sensor inconsistency",
  "difficulty": "easy",
  "provenance": {
    "source_type": "independent_synthesis",
    "source_file": "scripts/build_self_dataset.py",
    "source_index": 6,
    "adaptation": "Independently specified for this project; no public task was copied. The coding assistant chose the state variables, priority order and fixed scan traces, then reviewed the traces against a separate Python transition implementation.",
    "rationale": "A refill tank avoids contactor chatter between low and high level switches and detects physically inconsistent switch combinations.",
    "review": "Assistant consistency review of initialization, simultaneous commands, retained state and recovery boundaries; independent Python oracle checked against manual expected traces. Not an industrial safety certification or external expert review."
  },
  "requirements": "LowWet and HighWet indicate water covering the respective lower and upper switches. HighWet TRUE with LowWet FALSE is inconsistent: SensorFault TRUE and Fill FALSE. SensorFault is combinational and clears when inputs become consistent. Inhibit or HighWet also forces Fill FALSE. Otherwise LowWet FALSE starts Fill; LowWet TRUE and HighWet FALSE retains Fill. Fill initializes FALSE. Clearing Inhibit at a middle level retains the resulting stopped state until water falls below the low switch.",
  "scenario": "A refill tank avoids contactor chatter between low and high level switches and detects physically inconsistent switch combinations.",
  "interface": [
    {
      "direction": "INPUT",
      "name": "LowWet",
      "type": "BOOL",
      "description": "Water reaches lower switch"
    },
    {
      "direction": "INPUT",
      "name": "HighWet",
      "type": "BOOL",
      "description": "Water reaches upper switch"
    },
    {
      "direction": "INPUT",
      "name": "Inhibit",
      "type": "BOOL",
      "description": "External fill inhibit"
    },
    {
      "direction": "OUTPUT",
      "name": "Fill",
      "type": "BOOL",
      "description": "Inlet valve command"
    },
    {
      "direction": "OUTPUT",
      "name": "SensorFault",
      "type": "BOOL",
      "description": "Inconsistent level switches"
    }
  ],
  "initial_conditions": {
    "Fill": false
  },
  "scan_semantics": "At scan k, sample every input once, read retained pre-state q[k], execute one transition, and observe outputs O[k] at the end of that same scan. Updated state becomes q[k+1]. Reset the instance before each test. Step 0 executes normally; initial conditions describe pre-state, not an extra delayed scan. All timing in this task is explicitly counted in invocations, not wall time.",
  "safety_priority": [
    "Inconsistent sensors or Inhibit stop filling",
    "High switch stops",
    "Low switch starts",
    "Middle level retains"
  ],
  "assumptions": [],
  "atomic_propositions": {
    "LowWet": "Water reaches lower switch Boolean names are propositions; numeric names appear only inside defined predicates.",
    "HighWet": "Water reaches upper switch Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Inhibit": "External fill inhibit Boolean names are propositions; numeric names appear only inside defined predicates.",
    "Fill": "Inlet valve command Boolean names are propositions; numeric names appear only inside defined predicates.",
    "SensorFault": "Inconsistent level switches Boolean names are propositions; numeric names appear only inside defined predicates.",
    "first": "True only on the first invocation after resetting the FB instance.",
    "qFill": "Pre-scan retained Fill, initially FALSE.",
    "middle": "LowWet & !HighWet."
  },
  "ltl": [
    {
      "id": "P1",
      "formula": "G(SensorFault <-> (HighWet & !LowWet))",
      "explanation": "Fault exactly identifies inconsistent switches."
    },
    {
      "id": "P2",
      "formula": "G((SensorFault | Inhibit | HighWet) -> !Fill)",
      "explanation": "Inhibit, fault and full tank force shutoff."
    },
    {
      "id": "P3",
      "formula": "G((!LowWet & !HighWet & !Inhibit) -> Fill)",
      "explanation": "A low tank starts filling."
    },
    {
      "id": "P4",
      "formula": "G((middle & !Inhibit) -> (Fill <-> qFill))",
      "explanation": "The middle band retains the prior command."
    },
    {
      "id": "P5",
      "formula": "G(first -> !qFill)",
      "explanation": "No retained filling command exists on reset."
    }
  ],
  "tests": [
    {
      "id": "hysteresis",
      "purpose": "Fill cycle across both switching thresholds",
      "steps": [
        {
          "inputs": {
            "LowWet": false,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": true,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": true,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": true,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": true,
            "HighWet": true,
            "Inhibit": false
          },
          "expected": {
            "Fill": false,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": true,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": false,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": false,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": true,
            "SensorFault": false
          }
        }
      ]
    },
    {
      "id": "fault_inhibit",
      "purpose": "Invalid switch pair and inhibit recovery",
      "steps": [
        {
          "inputs": {
            "LowWet": true,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": false,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": false,
            "HighWet": true,
            "Inhibit": false
          },
          "expected": {
            "Fill": false,
            "SensorFault": true
          }
        },
        {
          "inputs": {
            "LowWet": false,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": true,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": true,
            "HighWet": false,
            "Inhibit": true
          },
          "expected": {
            "Fill": false,
            "SensorFault": false
          }
        },
        {
          "inputs": {
            "LowWet": true,
            "HighWet": false,
            "Inhibit": false
          },
          "expected": {
            "Fill": false,
            "SensorFault": false
          }
        }
      ]
    }
  ]
}
